'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,state;try{state=JSON.parse(localStorage.getItem('werkstatt-v1')||'{}')}catch{state={};storageOK=false}state.done||={};state.answers||={};state.scores||={};state.known||={};state.plan||={};state.writing||={};state.exam||={};state.log||={};state.hint||={};state.tries||={};state.leitner||={};state.rate||=0.9;
function save(){try{localStorage.setItem('werkstatt-v1',JSON.stringify(state))}catch{storageOK=false;$('.badge').textContent='Storage unavailable'}try{publish()}catch(e){}}

// ===== added helpers: activity log, speech, spelling distance, theme =====
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
function logAct(ok){const t=today();const l=state.log[t]||(state.log[t]={n:0,c:0});l.n++;if(ok)l.c++;save();updateHead()}
function streak(){let n=0;const d=new Date();if(!state.log[today()])d.setDate(d.getDate()-1);for(;;){const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');if(state.log[k]?.n){n++;d.setDate(d.getDate()-1)}else break}return n}
function updateHead(){const el=$('#streak');if(el){const s=streak(),t=state.log[today()]?.n||0;el.textContent=`🔥 ${s} day${s===1?'':'s'} · ${t} today`}}
const hasTTS='speechSynthesis' in window;
function speak(text){if(!hasTTS)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';const v=speechSynthesis.getVoices().find(v=>/^en-GB/i.test(v.lang))||speechSynthesis.getVoices().find(v=>/^en/i.test(v.lang));if(v)u.voice=v;u.rate=state.rate||0.9;speechSynthesis.speak(u)}
function spk(text,label=''){return hasTTS?`<button type="button" class="speak" data-say="${esc(text)}" aria-label="Listen: ${esc(text)}">🔊${label?' '+label:''}</button>`:''}
document.addEventListener('click',e=>{const b=e.target.closest('[data-say]');if(b){e.preventDefault();speak(b.dataset.say)}});
function lev(a,b){const m=a.length,n=b.length,d=Array.from({length:m+1},(_,i)=>[i]);for(let j=1;j<=n;j++)d[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[m][n]}
function nearMiss(v,a){const x=norm(v);if(!x)return null;let best=null;for(const ans of a){const y=norm(ans),dist=lev(x,y);if(dist>0&&dist<=Math.max(1,Math.floor(y.length/6))&&y.length>3&&(!best||dist<best.d))best={d:dist,ans}}return best}
function applyTheme(){document.documentElement.dataset.theme=state.theme==='dark'?'dark':'light';const b=$('#themebtn');if(b)b.textContent=state.theme==='dark'?'☀️':'🌙'}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';save();applyTheme()}
const norm=s=>s.toLowerCase().replace(/[’‘]/g,"'").replace(/isn't/g,'is not').replace(/wouldn't/g,'would not').replace(/hadn't/g,'had not').replace(/\bthe\b/g,'the').replace(/[.,?!;:]/g,'').replace(/[‐–—]/g,'-').replace(/\s+/g,' ').trim();
const correct=(v,a)=>a.some(x=>norm(x)===norm(v));
const modules=[['Tools & PPE','Name tools and explain workplace safety.','A1','Tools, safety goggles, hard hat','Wear safety goggles when drilling.','Personal protective equipment (PPE) protects workers. Learn tool names as complete technical terms.'],['Technical processes','Describe technical processes precisely.','B1','Present Simple · Present Continuous','A compressor increases the pressure of a gas.','Use the present simple for general operating principles and the present continuous for temporary activities. This module grouping is an added study structure.'],['Automotive engineering','From the piston to the crankshaft.','A2','Engine components · passive voice','The mixture is ignited by the spark plug.','The four strokes are intake, compression, power and exhaust. The passive voice focuses on the process: be + past participle.'],['Electric vehicles','Drive systems, batteries and regenerative braking.','A3','Range · regenerative braking','The inverter converts DC into AC.','During braking, the motor acts as a generator. In the source, exercise A3 covers Modules 4–6 together.'],['Energy & transition','Understand energy sources and heat pumps.','B3','Renewable energy · conditionals','If you heat ice, it melts.','Conditionals: Type 0 for general facts, Type 1 for real future possibilities, Type 2 for hypothetical situations and Type 3 for unreal past conditions.'],['Materials & properties','Describe materials and their properties.','B5','Composite · tensile strength','Carbon-fibre-reinforced plastic is a composite material.','Tensile strength describes resistance to breaking under tension. Information, oil and energy are uncountable; bolts, screws and kilowatts are countable.']];
const nav=[['home','Overview'],['modules','Modules 1–6'],['vocab','Vocabulary trainer'],['mistakes','My mistakes'],['games','Memory & activities'],['grammar','Grammar'],['b1','B1 grammar'],['b2','B2 grammar'],['reading','Reading'],['writing','Writing practice'],['exams','Practice exams'],['plan','Progress & plan'],['source','Source notes']];
let activeExam=null,tick=null,cardIndex=0,flipped=false;
function go(route){location.hash=route}function heading(k,t,p=''){return `<div class="eyebrow">${k}</div><h1>${t}</h1><p class="muted">${p}</p>`}
function progress(n,total){return `<div class="progress" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${total}" aria-label="Progress"><span style="width:${total?n/total*100:0}%"></span></div>`}
function groupBy(id){return DATA.groups.find(g=>g.id===id)}
function render(){clearInterval(tick);const [page='home',arg]=location.hash.slice(1).split('/');$('#nav').innerHTML=nav.map(([id,label])=>{const c=id==='mistakes'?mistakeIds().length:0;return `<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${label}${c?` <small>(${c})</small>`:''}</a>`}).join('');updateHead();const root=$('main');root.innerHTML=({home,games,modules:()=>modulePage(arg),vocab,mistakes,b1:()=>b1Page(arg),b2:()=>b2Page(arg),test:()=>testPage(arg),grammar:()=>grammar(arg),reading:()=>reading(arg),writing:()=>writing(arg),exams:()=>examPage(arg),plan,source}[page]||home)();if(!storageOK)$('.badge').textContent='Storage unavailable';if(page==='exams'&&arg&&state.exam[arg]?.started&&!state.exam[arg].finished)startTick(arg);window.scrollTo(0,0)}
function home(){const done=Object.keys(state.done).length;return heading('Your learning space','Understand engineering.<br>Use English with confidence.','Your practice space for English for Mechanical Engineers.')+`<section class="hero"><div><div class="eyebrow">Short sessions. Steady progress.</div><h2>Get ready for your English test.</h2><p>Practise technical vocabulary, understand grammar and train under exam conditions. At your own pace.</p><button onclick="go('modules')">Start learning</button></div><div class="schematic"><svg viewBox="0 0 300 200" fill="none" aria-label="Piston schematic" role="img"><g stroke="#9cbcb0" stroke-width="2"><path d="M60 20h180v110H60zM80 20v85h140V20M70 54h160M70 64h160M150 105v40l35 25"/><circle cx="185" cy="170" r="24"/><circle cx="185" cy="170" r="7"/><path d="M35 40H15v100h70M250 40h35v100h-60" stroke-dasharray="5 5"/></g><path d="M80 70h140v35H80z" fill="#d6ee94" fill-opacity=".6"/><text x="15" y="190" fill="#d6ee94" font-size="12" font-family="monospace">LEARN / PRACTISE / APPLY</text></svg></div></section><div class="grid"><div class="card"><small>Exercises checked</small><div class="stat">${done}<small> / 46</small></div>${progress(done,46)}</div><div class="card"><small>Vocabulary cards mastered</small><div class="stat">${Object.values(state.known).filter(Boolean).length}<small> / ${cards().length}</small></div><p class="muted">German and English in both directions</p></div><div class="card"><small>Your practice target</small><div class="stat">40<small> / 60 points</small></div><p class="muted">Practice exams · 90 minutes each</p></div></div><h2 class="sectionhead">Today</h2><div class="today"><div class="card"><small>Mistakes to review</small><div class="stat">${mistakeIds().length}</div><p class="muted">Wrong answers wait here until you get them right.</p><button ${mistakeIds().length?'':'disabled'} onclick="go('mistakes')">Review mistakes</button></div><div class="card"><small>Flashcards due</small><div class="stat">${dueCards().length}</div><p class="muted">Spaced repetition decides what to review.</p><button onclick="go('vocab')">Review flashcards</button></div><div class="card"><small>Recommended next</small>${(()=>{const w=weakest();return `<div class="stat" style="font-size:22px">${esc(w.label)}</div><p class="muted">${esc(w.why)}</p><button onclick="go('${w.route}')">Practise now</button>`})()}</div></div><div class="row spread"><h2>Your six learning modules</h2><a href="#modules">View all modules</a></div>${moduleCards()}<div class="notice">These practice exams are exercises from your file. The official exam format and pass mark have not been confirmed.</div>`}
function moduleCards(){return `<div class="grid">${modules.map((m,i)=>`<article class="card module"><span class="num">MODULE ${i+1}</span><h3>${m[0]}</h3><p class="muted">${m[1]}</p><a href="#modules/${i}">Open module</a></article>`).join('')}</div>`}
function modulePage(arg){if(arg===undefined)return heading('Learning modules','Build your technical foundation','Topic-based learning paths using the exercises from your TXT file.')+`<div class="notice">The file identifies Module 1, Module 3 and the Modules 4–6 topic block. The more detailed grouping, especially Module 2, is an added study structure, not a confirmed course syllabus.</div>`+moduleCards();const i=Number(arg),m=modules[i];if(!m)return modulePage();return heading(`Module ${i+1}`,m[0],m[1])+`<div class="card"><h2>${m[3]}</h2><p>${m[5]}</p><p lang="en"><strong>${m[4]}</strong></p><div class="toolbar"><button onclick="go('${m[2][0]==='A'?'vocab':'grammar'}/${m[2]}')">Open matching exercises</button><button class="secondary" onclick="go('reading/${i===3?1:0}')">Practise reading</button></div></div><h2 class="sectionhead">Put it into practice</h2>`+exercise(groupBy(m[2]),false)}
function exercise(g,exam=false){return `<section class="card"><h2>${esc(g.id+' · '+g.title)}</h2><p class="muted">${g.b1?'Type the missing words, or choose an option. Press Enter to check.':'Enter only the missing word or sentence ending. For sentence corrections, write the complete sentence.'}</p>${g.questions.map((q,i)=>{let id=g.id+'-'+i;return `<div class="question"><label for="q-${id}" lang="${g.id==='A1'||g.id==='A2'?'de':'en'}">${i+1}. ${q.t==='order'?'<span class="tag">word order</span> ':q.t==='fix'?'<span class="tag">error correction</span> ':''}${esc(q.q)}</label>${answerField(g.id,i,q,id)}<div class="toolbar">${q.opts||q.t==='order'?'':`<button onclick="check('${g.id}',${i})">Check answer</button><button class="secondary" onclick="hint('${g.id}',${i})">💡 Hint</button>`}${state.done[id]===true?'<span class="muted">✓ correct last time</span>':state.done[id]===false?'<span class="muted">✗ wrong last time</span>':''}</div><div id="f-${id}" class="feedback" role="status"></div></div>`}).join('')}<div class="summary" id="sum-${g.id}"><span>Check the whole worksheet at once.</span><button onclick="checkAll('${g.id}')">Check all</button></div></section>`}
function check(gid,i,silent){const q=groupBy(gid).questions[i],id=gid+'-'+i,v=$('#q-'+id).value,ok=correct(v,q.a);const near=!ok&&nearMiss(v,q.a);if(!v.trim()&&silent)return null;state.tries[id]=(state.tries[id]||0)+1;state.done[id]=ok;logAct(ok);save();const el=$('#f-'+id);el.className='feedback'+(ok?'':near?' almost':' bad');el.innerHTML=ok?`<strong>Correct.</strong> <span lang="en">${esc(q.a.join(' / '))}</span>${spk(q.a[0])}${m3d(q.a.join(' / '))}<br>${esc(q.ex)}`:near?`<strong>Almost!</strong> Check your spelling. Correct form: <span lang="en">${esc(near.ans)}</span>${spk(near.ans)}${m3d(near.ans)}<br>${esc(q.ex)}`:`<strong>Not quite yet.</strong> Answer: <span lang="en">${esc(q.a.join(' / '))}</span>${spk(q.a[0])}${m3d(q.a.join(' / '))}<br>${esc(q.ex)}`;return ok}
const orderSel={},orderShuf={};
function orderWords(q){const w=q.a[0].replace(/[.?!]$/,'').split(' ');if(w[0]!=='I'&&!/^[A-Z]{2}/.test(w[0]))w[0]=w[0][0].toLowerCase()+w[0].slice(1);return w}
function orderView(gid,i,id){const q=groupBy(gid).questions[i],w=orderWords(q);orderShuf[id]||=shuffled(w.map((_,k)=>k));const sel=orderSel[id]||(orderSel[id]=[]);return `<div class="orderline" aria-live="polite">${sel.length?sel.map(k=>`<span class="chip on">${esc(w[k])}</span>`).join(' '):'<span class="muted">Click the words in the right order …</span>'}</div><div class="chips">${orderShuf[id].map(k=>`<button type="button" class="chip" ${sel.includes(k)?'disabled':''} onclick="orderPick('${gid}',${i},${k})">${esc(w[k])}</button>`).join('')}</div><div class="toolbar"><button type="button" class="secondary" onclick="orderUndo('${gid}',${i})" ${sel.length?'':'disabled'}>↶ Undo</button><button type="button" class="secondary" onclick="orderReset('${gid}',${i})">Reset</button><button type="button" onclick="check('${gid}',${i})" ${sel.length===w.length?'':'disabled'}>Check sentence</button><button type="button" class="secondary" onclick="hint('${gid}',${i})">💡 Hint</button></div>`}
function orderSync(gid,i){const id=gid+'-'+i,q=groupBy(gid).questions[i],w=orderWords(q);$('#q-'+id).value=(orderSel[id]||[]).map(k=>w[k]).join(' ');$('#ow-'+id).innerHTML=orderView(gid,i,id)}
function orderPick(gid,i,k){const id=gid+'-'+i;(orderSel[id]||(orderSel[id]=[])).push(k);orderSync(gid,i)}
function orderUndo(gid,i){orderSel[gid+'-'+i]?.pop();orderSync(gid,i)}
function orderReset(gid,i){orderSel[gid+'-'+i]=[];orderSync(gid,i)}
function answerField(gid,i,q,id,fresh){if(q.t==='order'){orderSel[id]=[];return `<input type="hidden" id="q-${id}" value=""><div id="ow-${id}">${orderView(gid,i,id)}</div>${hintLine(gid,i)}`}if(q.opts){const v=fresh?'':(state.answers[id]||'');return `<input type="hidden" id="q-${id}" value="${esc(v)}"><div class="quizoptions">${q.opts.map(o=>`<button type="button" class="${norm(v)===norm(o)?'':'secondary'}" onclick="pickOpt('${gid}',${i},this)" data-opt="${esc(o)}">${esc(o)}</button>`).join('')}</div>`}return `<input id="q-${id}" value="${fresh?'':esc(state.answers[id]||'')}" autocomplete="off" spellcheck="false" oninput="state.answers['${id}']=this.value;save()" onkeydown="if(event.key==='Enter'){event.preventDefault();check('${gid}',${i})}">${hintLine(gid,i)}`}
function pickOpt(gid,i,btn){const id=gid+'-'+i;$('#q-'+id).value=btn.dataset.opt;state.answers[id]=btn.dataset.opt;btn.parentElement.querySelectorAll('button').forEach(b=>b.className=b===btn?'':'secondary');check(gid,i)}
function hintLine(gid,i){const id=gid+'-'+i,n=state.hint[id]||0;if(!n)return `<p class="hintline" id="h-${id}"></p>`;const q0=groupBy(gid).questions[i],a=q0.a[0];if(q0.t==='order'){const w=a.split(' ');return `<p class="hintline" id="h-${id}">${esc(w.slice(0,n).join(' '))}${n<w.length?' …':''}</p>`}return `<p class="hintline" id="h-${id}">${esc([...a].map((c,k)=>c===' '||c==='-'?c:k<n?c:'_').join(''))}</p>`}
function hint(gid,i){const id=gid+'-'+i,q0=groupBy(gid).questions[i],a=q0.a[0];state.hint[id]=Math.min((state.hint[id]||0)+1,q0.t==='order'?a.split(' ').length:a.length);save();$('#h-'+id).outerHTML=hintLine(gid,i)}
function checkAll(gid){const g=groupBy(gid);let ok=0,tried=0;g.questions.forEach((_,i)=>{const r=check(gid,i,true);if(r!==null){tried++;if(r)ok++}});const wrong=g.questions.length-ok;$('#sum-'+gid).innerHTML=`<span><strong>${ok}/${g.questions.length} correct</strong>${tried<g.questions.length?` · ${g.questions.length-tried} unanswered`:''}</span>${wrong?`<button onclick="go('mistakes')">Practise my mistakes</button>`:'<span>Excellent – all correct! 🎉</span>'}`}
function levelStats(lv){const p=LEVELS[lv].prefix;const gs=groupStats(true).filter(g=>g.id[0]===p);return {groups:gs,c:gs.reduce((a,g)=>a+g.c,0),t:gs.reduce((a,g)=>a+g.t,0),n:gs.reduce((a,g)=>a+g.n,0)}}
function b1Stats(){const gs=groupStats(true).filter(g=>/^G/.test(g.id));return {groups:gs,c:gs.reduce((a,g)=>a+g.c,0),t:gs.reduce((a,g)=>a+g.t,0),n:gs.reduce((a,g)=>a+g.n,0)}}
function mistakeIds(){return Object.entries(state.done).filter(([,v])=>v===false).map(([k])=>k).filter(k=>groupBy(k.split('-')[0]))}

function b1Page(arg){return unitPage('b1',arg)}
function b2Page(arg){return unitPage('b2',arg)}
function unitPage(lv,arg){const L=LEVELS[lv],T=L.topics,st=levelStats(lv),t=T.find(x=>x.id===arg),lt=state.ltest?.[lv],best=(state.ltestHistory?.[lv]||[]).reduce((m,r)=>Math.max(m,Math.round(r.score/r.total*100)),0);
if(!t)return heading('Grammar · CEFR '+L.name,L.name+' grammar unit',`${T.length} core ${L.name} grammar topics. Each topic: rules with examples, a tip for German speakers and exercises – fill the gap, multiple choice, word order and error correction.`)+`<div class="toolbar">${Object.entries(LEVELS).map(([k,v])=>`<button class="${k===lv?'':'secondary'}" onclick="go('${k}')">${v.name} grammar</button>`).join('')}<button class="secondary" onclick="go('test/${lv}')">📝 ${L.name} final test</button></div><div class="grid"><div class="card"><small>Exercises correct</small><div class="stat">${st.c}<small> / ${st.n}</small></div>${progress(st.c,st.n)}</div><div class="card"><small>Topics completed (all correct)</small><div class="stat">${st.groups.filter(g=>g.c===g.n).length}<small> / ${T.length}</small></div>${progress(st.groups.filter(g=>g.c===g.n).length,T.length)}</div><div class="card"><small>${L.name} final test · best result</small><div class="stat">${best?best+'%':'–'}</div><button onclick="go('test/${lv}')">${lt&&!lt.finished?'Continue test':'Take the test'}</button></div></div><div class="grid">${T.map((x,k)=>{const g=st.groups[k];return `<article class="card module"><span class="num">TOPIC ${k+1}</span><h3>${esc(x.title)}</h3><p class="muted">${esc(x.de)}</p>${progress(g.c,g.n)}<small>${g.c}/${g.n} correct</small><a href="#${lv}/${x.id}">${g.t?'Continue':'Start'} topic</a></article>`}).join('')}</div><div class="notice">Topics follow the common CEFR ${L.name} grammar syllabus. Explanations and exercises are original material written for this course, with engineering examples. For extra practice see the free exercises on <a href="https://test-english.com/grammar-points/" target="_blank" rel="noopener">test-english.com</a>.</div>`;
const k=T.indexOf(t),prev=T[k-1],next=T[k+1];return heading(`${L.name} grammar · Topic ${k+1} of ${T.length}`,esc(t.title),esc(t.de))+`<section class="card"><h2>Rules</h2>${t.rules.map(([r,e])=>`<div class="question"><p style="margin:0 0 6px">${esc(r)}</p><p lang="en" style="margin:0"><strong>${esc(e)}</strong>${spk(e)}</p></div>`).join('')}<div class="notice warn" lang="de"><strong>Tipp für Deutschsprachige:</strong> ${esc(t.tip)}</div></section><h2 class="sectionhead">Practice</h2>${exercise(groupBy(t.id))}<div class="toolbar">${prev?`<button class="secondary" onclick="go('${lv}/${prev.id}')">← ${esc(prev.title)}</button>`:''}<button class="secondary" onclick="go('${lv}')">All topics</button>${next?`<button onclick="go('${lv}/${next.id}')">${esc(next.title)} →</button>`:`<button onclick="go('test/${lv}')">📝 Final test</button>`}</div>`}

// ===== final level test: 20 random questions, at least one per topic =====
function testPage(arg){const lv=arg==='b2'?'b2':'b1',L=LEVELS[lv];state.ltest||={};state.ltestHistory||={};const t=state.ltest[lv],hist=state.ltestHistory[lv]||[];
const histHtml=hist.length?`<section class="card sectionhead"><h2>Your results</h2>${hist.slice().reverse().map(r=>`<div class="barrow" style="grid-template-columns:110px 1fr 70px"><small>${esc(r.date)}</small><div class="progress"><span style="width:${r.score/r.total*100}%"></span></div><strong>${r.score}/${r.total}</strong></div>`).join('')}</section>`:'';
if(!t)return heading('Final test · '+L.name,L.name+' grammar test',`20 questions from all ${L.topics.length} topics, in random order. No hints and no feedback until you submit.`)+`<div class="card"><p>Fill the gaps, choose options and correct mistakes. When you submit, you see your score, every correct answer and the topics you should review.</p><p class="muted">Pass mark used here: 70 % (a study target, not an official CEFR certificate).</p><button onclick="startTest('${lv}')">Start the ${L.name} test</button> <button class="secondary" onclick="go('${lv}')">Back to topics</button></div>`+histHtml;
const qs=t.ids.map(k=>{const[g,i]=k.split('-');return {k,g,i:+i,q:groupBy(g).questions[+i],topic:L.topics.find(x=>x.id===g)}});
if(!t.finished)return heading('Final test · '+L.name,L.name+' grammar test',`${qs.length} questions · answers are saved automatically`)+`<section class="card">${qs.map((x,n)=>`<div class="question"><label for="t-${x.k}">${n+1}. ${x.q.t==='fix'?'<span class="tag">error correction</span> ':''}${esc(x.q.q)}</label>${x.q.opts?`<div class="quizoptions">${x.q.opts.map(o=>`<button type="button" class="${t.answers[x.k]===o?'':'secondary'}" onclick="testPick('${lv}','${x.k}',this)" data-opt="${esc(o)}">${esc(o)}</button>`).join('')}</div>`:`<input id="t-${x.k}" value="${esc(t.answers[x.k]||'')}" autocomplete="off" spellcheck="false" oninput="state.ltest['${lv}'].answers['${x.k}']=this.value;save()">`}</div>`).join('')}<div class="toolbar"><button onclick="finishTest('${lv}')">Submit test</button><button class="secondary" onclick="if(confirm('Cancel this test?')){delete state.ltest['${lv}'];save();render()}">Cancel</button></div></section>`;
const res=qs.map(x=>({...x,ok:correct(t.answers[x.k]||'',x.q.a)})),score=res.filter(r=>r.ok).length,pct=Math.round(score/res.length*100);const weak=[...new Map(res.filter(r=>!r.ok).map(r=>[r.g,r.topic])).values()];
return heading('Final test · '+L.name,`Result: ${score} / ${res.length} (${pct} %)`,pct>=70?`Well done – you reached the ${L.name} practice target of 70 %.`:'Not yet at the 70 % target. Review the topics below and try again.')+`<div class="grid two"><div class="card"><small>Score</small><div class="stat">${pct}%</div>${progress(score,res.length)}<p class="muted">${pct>=85?'Excellent – this level looks secure.':pct>=70?'Good – a few gaps remain.':'Keep practising the topics below.'}</p></div><div class="card"><small>Topics to review</small>${weak.length?`<ul>${weak.map(w=>`<li><a href="#${lv}/${w.id}">${esc(w.title)}</a></li>`).join('')}</ul>`:'<p>None – every answer was correct! 🎉</p>'}</div></div><section class="card sectionhead"><h2>Answers</h2>${res.map((r,n)=>`<div class="question"><p style="margin:0 0 6px">${n+1}. ${esc(r.q.q)}</p><div class="feedback ${r.ok?'':'bad'}"><strong>${r.ok?'✓':'✗'}</strong> Your answer: ${esc(t.answers[r.k]||'—')} · Correct: <span lang="en">${esc(r.q.a.join(' / '))}</span>${spk(r.q.a[0])}<br><small>${esc(r.q.ex)} · Topic: ${esc(r.topic.title)}</small></div></div>`).join('')}</section><div class="toolbar"><button onclick="startTest('${lv}')">New test</button><button class="secondary" onclick="go('${lv}')">Back to topics</button></div>`+histHtml}
function startTest(lv){const L=LEVELS[lv];const pool=t=>groupBy(t.id).questions.map((q,i)=>({k:t.id+'-'+i,q})).filter(x=>x.q.t!=='order');let ids=L.topics.map(t=>{const p=pool(t);return p[Math.floor(Math.random()*p.length)].k});const rest=shuffled(L.topics.flatMap(pool).map(x=>x.k).filter(k=>!ids.includes(k)));while(ids.length<20&&rest.length)ids.push(rest.pop());state.ltest[lv]={ids:shuffled(ids),answers:{},started:Date.now(),finished:false};save();render()}
function testPick(lv,k,btn){state.ltest[lv].answers[k]=btn.dataset.opt;save();btn.parentElement.querySelectorAll('button').forEach(b=>b.className=b===btn?'':'secondary')}
function finishTest(lv){const t=state.ltest[lv];const qs=t.ids.map(k=>{const[g,i]=k.split('-');return groupBy(g).questions[+i]});const empty=t.ids.filter(k=>!(t.answers[k]||'').trim()).length;if(empty&&!confirm(`${empty} question(s) are empty. Submit anyway?`))return;const score=t.ids.filter((k,n)=>correct(t.answers[k]||'',qs[n].a)).length;t.finished=true;t.score=score;(state.ltestHistory[lv]||(state.ltestHistory[lv]=[])).push({date:today(),score,total:t.ids.length});logAct(score/t.ids.length>=0.7);save();render()}
function mistakes(){const ids=mistakeIds();if(!ids.length)return heading('Review','My mistakes','Every wrong answer from the worksheets appears here until you answer it correctly.')+`<div class="card"><h2>Nothing to review 🎉</h2><p>Either you have not checked any exercises yet, or every checked answer is correct.</p><button onclick="go('vocab/A1')">Start with worksheet A1</button></div>`;const by={};ids.forEach(k=>{const[g,i]=k.split('-');(by[g]||(by[g]=[])).push(+i)});return heading('Review','My mistakes',`${ids.length} item${ids.length===1?'':'s'} to review. Correct answers disappear from this list.`)+Object.entries(by).map(([gid,list])=>{const g=groupBy(gid);return `<section class="card sectionhead"><h2>${esc(g.id+' · '+g.title)}</h2>${list.map(i=>{const q=g.questions[i],id=gid+'-'+i;return `<div class="question"><label for="q-${id}">${esc(q.q)} <small>· ${state.tries[id]||1} attempt${(state.tries[id]||1)===1?'':'s'}</small></label>${answerField(gid,i,q,id,true)}<div class="toolbar">${q.opts||q.t==='order'?'':`<button onclick="check('${gid}',${i})">Check answer</button><button class="secondary" onclick="hint('${gid}',${i})">💡 Hint</button>`}</div><div id="f-${id}" class="feedback" role="status"></div></div>`}).join('')}</section>`}).join('')+`<div class="toolbar"><button class="secondary" onclick="render()">Refresh list</button></div>`}
const pairs=[['Schutzhandschuhe','protective gloves'],['Schraubenzieher','screwdriver'],['Zylinder','cylinder'],['Ladestation','charging station'],['Reichweite','range'],['erneuerbare Energie','renewable energy'],['Verbundwerkstoff','composite'],['Druck','pressure'],['Wirkungsgrad','efficiency'],['Zugfestigkeit','tensile strength'],['Windkraftanlage','wind turbine'],['fossile Brennstoffe','fossil fuels'],['Rekuperation','regenerative braking']];
function cards(){return [...DATA.groups[0].questions.map(q=>[q.q.replace(/:.*$/,'').replace(/ \(.*?\)/g,''),q.a[0]]),...DATA.groups[1].questions.map(q=>[q.q,q.a.join(' / ')]),...pairs]}
function vocab(){const arg=location.hash.split('/')[1];if(arg&&groupBy(arg))return heading('Technical vocabulary','Recall actively, apply confidently')+exercise(groupBy(arg));return heading('Technical vocabulary trainer','One term. Two languages.','Turn the card over, assess your recall and review the terms.')+`<div class="row"><label for="direction">Direction</label><select id="direction" onchange="state.direction=this.value;flipped=false;save();render()"><option value="de">German → English</option><option value="en" ${state.direction==='en'?'selected':''}>English → German</option></select></div>${flash()}<h2 class="sectionhead">Worksheet A from your file</h2><div class="grid">${DATA.groups.slice(0,3).map(g=>`<div class="card"><h3>${g.id}</h3><p>${esc(g.title)}</p><button onclick="go('vocab/${g.id}')">Practise</button></div>`).join('')}</div>`}
const BOX_DAYS=[0,1,3,7,16];
function cardKey(c){return c[0]+'|'+c[1]}
function dueCards(){const now=Date.now();return cards().map((c,i)=>({c,i,l:state.leitner[cardKey(c)]})).filter(x=>!x.l||x.l.due<=now)}
function pickCard(){const due=dueCards();if(!due.length)return cardIndex%cards().length;const unseen=due.filter(x=>!x.l);const pool=due.filter(x=>x.l).sort((a,b)=>a.l.due-b.l.due);return (pool[0]||unseen[0]).i}
let curCard=null;
function flash(){const list=cards();if(curCard===null)curCard=pickCard();const i=curCard,c=list[i],side=state.direction==='en'?1:0,l=state.leitner[cardKey(c)],box=l?.box||0,due=dueCards().length;return `<div id="flash" class="card flash"><small>CARD ${i+1} / ${list.length} · ${due} due now · box ${box}/4</small><div class="boxes" aria-hidden="true">${[1,2,3,4].map(b=>`<span class="${box>=b?'on':''}"></span>`).join('')}</div><strong lang="${side?'en':'de'}">${esc(c[side])}${side?spk(c[1].split(' / ')[0]):''}</strong><p lang="${side?'de':'en'}">${flipped?esc(c[1-side])+(side?'':spk(c[1].split(' / ')[0]))+m3d(c[1]):'Try to recall the answer first.'}</p><div class="toolbar">${flipped?`<button class="secondary" onclick="nextCard(false)">Review again</button><button onclick="nextCard(true)">Got it!</button>`:`<button onclick="flipped=true;$('#flash').outerHTML=flash()">Show answer</button>`}<button class="secondary" onclick="curCard=(curCard+1)%cards().length;flipped=false;$('#flash').outerHTML=flash()">Skip</button></div><small>Spaced repetition: “Got it” moves the card up a box (review after ${BOX_DAYS.slice(1).join(' / ')} days); “Review again” sends it back to box 0.</small></div>`}
function nextCard(known){const list=cards(),c=list[curCard],k=cardKey(c),l=state.leitner[k]||{box:0,due:0};l.box=known?Math.min(4,l.box+1):0;l.due=Date.now()+(known?BOX_DAYS[l.box]*86400000:60000);state.leitner[k]=l;state.known[curCard]=l.box>=2;logAct(known);save();curCard=pickCard();if(curCard===list.indexOf(c)&&dueCards().length>1)curCard=dueCards().find(x=>x.i!==curCard).i;flipped=false;$('#flash').outerHTML=flash()}
function grammar(arg){return heading('Grammar workshop','Understand rules. Build sentences.','Automatic checking with English explanations. Other correct formulations may differ from the answer key.')+`<div class="toolbar">${DATA.groups.filter(g=>!g.b1).slice(3).map(g=>`<button class="${arg===g.id?'':'secondary'}" onclick="go('grammar/${g.id}')">${g.id} · ${g.title.split('?')[0]}</button>`).join('')}</div>`+exercise(groupBy(arg)||DATA.groups[3])+`<div class="notice">More grammar: <a href="#b1">B1 unit (20 topics)</a> · <a href="#b2">B2 unit (16 topics)</a> · <a href="#test/b1">final tests</a></div>`}
function reading(arg){let n=Number(arg)||0;return heading('Reading','Read. Understand. Explain.','Answer the questions in English, then compare your answer with the sample answer.')+`<div class="toolbar"><button onclick="go('reading/0')">Heat pump</button><button class="secondary" onclick="go('reading/1')">Electric vehicles</button></div>`+readBlock(n,false)}
function readBlock(n,isExam){const e=DATA.exams[n];return `<article class="card"><h2 lang="en">${n?'Electric vehicles':'How a heat pump works'}</h2><p class="reading" lang="en">${esc(e.reading)}</p>${hasTTS?`<div class="toolbar">${spk(e.reading,'Listen to the text')}<button class="secondary" onclick="speechSynthesis.cancel()">⏹ Stop</button></div>`:''}</article><section class="card sectionhead"><h2>Reading comprehension · 15 points</h2>${e.read.map((q,i)=>freeQ(n,'r',i,q,isExam)).join('')}</section>`}
function freeQ(n,type,i,q,isExam){const key=`${n}-${type}-${i}`,val=isExam?(state.exam[n]?.answers?.[key]||''):(state.answers[key]||'');const finished=state.exam[n]?.finished;return `<div class="question"><label for="free-${key}" lang="en">${i+1}. ${esc(q.q)}</label><textarea id="free-${key}" ${isExam&&finished?'readonly':''} oninput="freeSave(${n},'${type}',${i},this.value,${isExam})">${esc(val)}</textarea>${!isExam||finished?`<details><summary>Compare sample answer</summary><p lang="en">${esc(Array.isArray(q.a)?q.a.join(' / '):q.a)}</p>${q.added?'<small>Added example; no answer is provided in the source file.</small>':''}</details>`:''}</div>`}
function freeSave(n,t,i,v,isExam){const key=`${n}-${t}-${i}`;if(isExam){if(state.exam[n].finished)return;state.exam[n].answers[key]=v}else state.answers[key]=v;save()}
function writing(arg){let n=Number(arg)||0;return heading('Writing practice','Make your explanation work.','Technical description · 150–200 words · at least three passive sentences.')+`<div class="toolbar"><button onclick="go('writing/0')">Four-stroke engine</button><button class="secondary" onclick="go('writing/1')">Air compressor</button></div><div class="card"><h2>Technical description</h2><p lang="en">${esc(DATA.exams[n].writing)}</p><label for="draft">Your English text</label><textarea id="draft" style="min-height:300px" oninput="state.writing[${n}]=this.value;save();$('#wordcount').textContent=wordCount(this.value)+' words'">${esc(state.writing[n]||'')}</textarea><p id="wordcount" role="status">${wordCount(state.writing[n]||'')} words</p><button onclick="writingFeedback(${n})">Review text with checklist</button><div id="writingFeedback" role="status"></div>${modelBlock(n)}</div>`}
function wordCount(s){return s.trim()?s.trim().split(/\s+/).length:0}
function writingFeedback(n){const text=$('#draft').value,w=wordCount(text),pass=(text.match(/\b(?:is|are)\s+(?:\w+ly\s+)?(?:\w+ed|built|drawn|driven|given|made|shown|taken|written)\b/gi)||[]).length;$('#writingFeedback').innerHTML=`<div class="notice"><strong>${w} words: ${w>=150&&w<=200?'Target length reached':'Target length: 150–200 words'}.</strong><p>Simple language hint: ${pass} possible passive forms found. This pattern search does not detect all passive forms or assess accuracy or quality.</p><ul><li>Content: ${n?'purpose, main components, intake, compression, storage and pressure control':'overview, intake, compression, power and exhaust; piston and valve actions in each stroke'} complete?</li><li>Structure: clear sequence, paragraphs and linking words?</li><li>Grammar: present simple and at least three correct passive sentences?</li><li>Technical vocabulary: appropriate technical terms used precisely?</li></ul><p>Marking scheme: Content 8 · Structure 4 · Grammar 4 · Technical vocabulary 4. This checklist does not provide a reliable automatic writing grade.</p></div>`}
function modelBlock(n){return `<details><summary>${n?'Added writing scaffold':'Sample answer from the file (excerpt)'}</summary><p lang="en">${esc(n?'An air compressor is used to supply compressed air for pneumatic tools. First, ... Next, ... The air is compressed ... It is stored ... When the set pressure is reached, ... Finally, ...':DATA.engineModel)}</p><small>${n?'Added study material. The source file does not provide a sample answer for this writing task.':'The source labels this as an excerpt; it is not a complete 150–200-word response.'}</small></details>`}
function examPage(arg){if(arg===undefined)return heading('Exam practice','Your rehearsal.','Two practice exams from the TXT file. Each lasts 90 minutes and is worth 60 points.')+`<div class="notice warn">Practice only: the official exam format has not been confirmed. Practise without a dictionary or phone. The source recommends a target of at least 40/60 points. The official pass mark is unknown.</div><div class="grid two">${DATA.exams.map((e,n)=>`<article class="card"><span class="eyebrow">90 minutes · 60 points</span><h2>Practice exam ${n+1}</h2><p>${n?'Electric vehicles & air compressor':'Heat pump & four-stroke engine'}</p><p>Reading 15 · Vocabulary 10 · Grammar 15 · Writing 20</p><button onclick="go('exams/${n}')">${state.exam[n]?.started?'Open attempt':'Prepare practice exam'}</button></article>`).join('')}</div>`;const n=Number(arg),e=DATA.exams[n];if(!e)return examPage();const a=state.exam[n];if(!a?.started)return heading('Practice · not an official format',`Practice exam ${n+1}`,'The timer begins when you select “Start 90 minutes”. Answers are saved locally.')+`<div class="card"><p>Your attempt is submitted automatically after 90 minutes. Reloading or switching pages does not pause the timer. Sample answers are shown only after submission.</p><p>Grammar${n===0?' and vocabulary':''} are checked automatically. Reading, writing${n===1?' and term definitions':''} are self-assessed using the sample answers.</p><button onclick="beginExam(${n})">Start 90 minutes</button></div>`;
return heading('Practice · not an official format',`Practice exam ${n+1}`)+`<div class="examtop row spread"><strong>${a.finished?'Submitted':'Attempt in progress'}</strong><span class="timer" id="timer">${remaining(a)}</span>${a.finished?`<button class="secondary" onclick="resetExam(${n})">New attempt</button>`:`<button onclick="finishExam(${n})">Submit now</button>`}</div>${a.finished?examResult(n):''}${readBlock(n,true)}<section class="card sectionhead"><h2>Vocabulary · 10 points</h2><p lang="en">${n?'Explain each term in one English sentence.':'Give the English technical term.'}</p>${e.vocab.map((q,i)=>freeQ(n,'v',i,q,true)).join('')}</section><section class="card sectionhead"><h2>Grammar · 15 points</h2><p>Questions 1–8: enter the missing verb form. Exam 1: rewrite 9–12 in the passive voice; correct the error in 13–15 (complete sentences). Exam 2: combine 9–11 into conditional sentences; enter the missing word in 12–15.</p>${e.grammar.map((q,i)=>freeQ(n,'g',i,q,true)).join('')}</section><section class="card sectionhead"><h2>Technical description · 20 points</h2><p lang="en">${esc(e.writing)}</p><label for="examtext">Your text</label><textarea id="examtext" ${a.finished?'readonly':''} style="min-height:300px" oninput="freeSave(${n},'w',0,this.value,true);$('#examwords').textContent=wordCount(this.value)+' words'">${esc(a.answers[`${n}-w-0`]||'')}</textarea><p id="examwords">${wordCount(a.answers[`${n}-w-0`]||'')} words</p>${a.finished?modelBlock(n):`<button onclick="finishExam(${n})">Submit attempt</button>`}</section>`}
function beginExam(n){state.exam[n]={started:Date.now(),answers:{},finished:false,manual:{}};save();render()}
function remaining(a){const s=Math.max(0,Math.ceil((a.started+90*60000-(a.finished?a.ended:Date.now()))/1000));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function startTick(n){function update(){const a=state.exam[n];if(a.finished)return;if(Date.now()>=a.started+90*60000){finishExam(n);return}if($('#timer'))$('#timer').textContent=remaining(a)}update();tick=setInterval(update,1000)}
function finishExam(n){if(state.exam[n].finished)return;state.exam[n].finished=true;state.exam[n].ended=Date.now();save();clearInterval(tick);render()}
function resetExam(n){if(confirm('Replace this attempt and its answers?')){delete state.exam[n];save();render()}}
function examAuto(n){let e=DATA.exams[n],a=state.exam[n].answers;return e.grammar.reduce((sum,q,i)=>sum+Number(correct(a[`${n}-g-${i}`]||'',q.a)),0)+(n===0?e.vocab.reduce((sum,q,i)=>sum+Number(correct(a[`${n}-v-${i}`]||'',q.a)),0):0)}
function manualFields(n){return [...DATA.exams[n].read.map((q,i)=>({key:'r'+i,label:'Reading '+(i+1),max:q.p})),...(n===1?DATA.exams[n].vocab.map((_,i)=>({key:'v'+i,label:'Vocabulary '+(i+1),max:1})):[]),...['Content','Structure','Grammar','Technical vocabulary'].map((x,i)=>({key:'w'+i,label:'Writing: '+x,max:[8,4,4,4][i]}))]}
function totalScore(n){const a=state.exam[n],fs=manualFields(n),complete=fs.every(f=>a.manual[f.key]!==undefined&&a.manual[f.key]!=='');return {auto:examAuto(n),manual:fs.reduce((s,f)=>s+Number(a.manual[f.key]||0),0),complete}}
function examResult(n){const score=totalScore(n);return `<section class="card sectionhead"><h2>Results</h2><p id="total" role="status">${scoreText(n)}</p><div class="notice">Automatic score: ${score.auto}/${n===0?25:15} points. Free-text answers are not automatically assessed for meaning. Compare your answers with the solutions below and enter your points. Automatic checking may miss other factually correct formulations.</div><details><summary>Enter self-assessment</summary><p>Reading: award points for the relevant content elements in each sample answer. Definitions: award 1 point for a factually correct English explanation. Writing: assess the four criteria up to their stated maximum.</p>${manualFields(n).map(f=>`<label for="m-${f.key}">${f.label} (0–${f.max})</label><input class="scoreinput" id="m-${f.key}" type="number" min="0" max="${f.max}" step="0.5" value="${state.exam[n].manual[f.key]??''}" oninput="manualScore(${n},'${f.key}',this,${f.max})">`).join('')}</details><button class="secondary" onclick="downloadExam(${n})">Download answers & results</button></section>`}
function scoreText(n){const s=totalScore(n),total=s.auto+s.manual;return `<strong>${total}/60 points ${s.complete?'(including self-assessment)':'so far (self-assessment incomplete)'}</strong>${s.complete?` · ${total>=40?'Practice target of 40/60 reached.':'Practice target of 40/60 not yet reached.'}`:''}`}
function manualScore(n,k,el,max){const v=el.value;state.exam[n].manual[k]=v===''?'':Math.max(0,Math.min(max,Math.round(Number(v)*2)/2));if(v!=='')el.value=state.exam[n].manual[k];save();$('#total').innerHTML=scoreText(n)}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadExam(n){let a=state.exam[n],e=DATA.exams[n],lines=[`Practice exam ${n+1} – Practice, not an official format`,scoreText(n).replace(/<[^>]+>/g,''),''];for(const [t,qs] of [['r',e.read],['v',e.vocab],['g',e.grammar]])qs.forEach((q,i)=>lines.push(q.q,a.answers[`${n}-${t}-${i}`]||'(blank)','Answer: '+(Array.isArray(q.a)?q.a.join(' / '):q.a),''));lines.push('Writing',a.answers[`${n}-w-0`]||'');download(`Practice exam-${n+1}.txt`,lines.join('\n'))}
function groupStats(all){return DATA.groups.filter(g=>all||!g.b1).map(g=>{let t=0,c=0;g.questions.forEach((_,i)=>{const v=state.done[g.id+'-'+i];if(v!==undefined){t++;if(v)c++}});return {id:g.id,title:g.title.split('.')[0].split('?')[0],n:g.questions.length,t,c}})}
function weakest(){const gs=groupStats();const untried=gs.find(g=>g.t===0);const tried=gs.filter(g=>g.t>0).sort((a,b)=>a.c/a.n-b.c/b.n);const route=g=>(g.id[0]==='A'?'vocab/':'grammar/')+g.id;if(mistakeIds().length>=5)return {label:'My mistakes',why:`${mistakeIds().length} wrong answers are waiting for review.`,route:'mistakes'};if(tried[0]&&tried[0].c/tried[0].n<0.6)return {label:tried[0].id+' · '+tried[0].title,why:`Your weakest worksheet so far: ${tried[0].c}/${tried[0].n} correct.`,route:route(tried[0])};if(untried)return {label:untried.id+' · '+untried.title,why:'You have not started this worksheet yet.',route:route(untried)};if(dueCards().length)return {label:'Flashcards',why:`${dueCards().length} cards are due.`,route:'vocab'};return {label:'Practice exam',why:'All worksheets look good – test yourself under exam conditions.',route:'exams'}}
function readiness(){const gs=groupStats(),ws=gs.reduce((s,g)=>s+g.c,0)/46,fl=cards().filter(c=>(state.leitner[cardKey(c)]?.box||0)>=2).length/cards().length;const ex=Math.max(0,...DATA.exams.map((_,n)=>state.exam[n]?.finished?(totalScore(n).auto+totalScore(n).manual)/60:0));return Math.round((ws*0.5+fl*0.2+ex*0.3)*100)}
function activityChart(){const days=[];const d=new Date();d.setDate(d.getDate()-13);for(let k=0;k<14;k++){const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');days.push({key,label:d.getDate()+'.'+(d.getMonth()+1)+'.',...(state.log[key]||{n:0,c:0})});d.setDate(d.getDate()+1)}const max=Math.max(5,...days.map(x=>x.n)),W=560,H=150,bw=W/14;return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Exercises per day in the last 14 days">${days.map((x,k)=>{const h=(x.n/max)*(H-34),hc=(x.c/max)*(H-34),X=k*bw+6;return `<g><rect x="${X}" y="${H-20-h}" width="${bw-12}" height="${h}" rx="3" fill="#e3b34c" opacity=".55"><title>${x.label}: ${x.n} answers, ${x.c} correct</title></rect><rect x="${X}" y="${H-20-hc}" width="${bw-12}" height="${hc}" rx="3" fill="var(--teal)"/>${x.n?`<text x="${X+(bw-12)/2}" y="${H-24-h}" text-anchor="middle">${x.n}</text>`:''}<text x="${X+(bw-12)/2}" y="${H-6}" text-anchor="middle">${x.label}</text></g>`}).join('')}</svg><div class="legend"><span><b style="background:var(--teal)"></b>correct</span><span><b style="background:#e3b34c;opacity:.55"></b>all answers</span></div>`}
function plan(){const done=Object.keys(state.done).length,right=Object.values(state.done).filter(Boolean).length;const tot=Object.values(state.log).reduce((a,l)=>({n:a.n+l.n,c:a.c+l.c}),{n:0,c:0}),r=readiness(),gs=groupStats(),w=weakest();return heading('Progress & study plan','Build a study routine.','Your data stays in this browser. This flexible study plan is an added learning recommendation.')+`<div class="grid"><div class="card"><small>Practice readiness (estimate)</small><div class="stat">${r}%</div>${progress(r,100)}<small>50 % worksheets · 20 % flashcards (box ≥ 2) · 30 % best practice exam. A study guide, not an exam prediction.</small></div><div class="card"><small>Streak & activity</small><div class="stat">🔥 ${streak()}</div><p class="muted">${tot.n} answers in total · ${tot.n?Math.round(tot.c/tot.n*100):0} % correct</p></div><div class="card"><small>Recommended next</small><h3>${esc(w.label)}</h3><p class="muted">${esc(w.why)}</p><button onclick="go('${w.route}')">Practise now</button></div></div><div class="grid two"><section class="card"><h2>Last 14 days</h2>${activityChart()}</section><section class="card"><h2>Worksheets</h2>${gs.map(g=>`<div class="barrow"><strong>${g.id}</strong><div class="progress" title="${g.c} correct, ${g.t} attempted of ${g.n}"><i style="width:${g.t/g.n*100}%"></i><span style="width:${g.c/g.n*100}%"></span></div><small>${g.c}/${g.n} ✓</small></div>`).join('')}<div class="legend"><span><b style="background:var(--teal)"></b>correct</span><span><b style="background:#e3b34c;opacity:.55"></b>attempted</span></div><p><a href="#mistakes">${mistakeIds().length} mistakes to review →</a></p></section></div><div class="grid"><div class="card"><small>Exercises attempted</small><div class="stat">${done}/46</div>${progress(done,46)}</div><div class="card"><small>Correct on last check</small><div class="stat">${right}/46</div>${progress(right,46)}</div><div class="card"><small>Study sessions completed</small><div class="stat">${Object.values(state.plan).filter(Boolean).length}/8</div>${progress(Object.values(state.plan).filter(Boolean).length,8)}</div></div><section class="card"><h2>Your study plan</h2><label for="testdate">Your exam date (optional)</label><input id="testdate" type="date" value="${esc(state.testdate||'')}" onchange="state.testdate=this.value;save();render()"><p>${state.testdate?daysUntil():'Set a date to see the time remaining. The source lists 15 January and 22 January without a year, so no fixed dates are assumed.'}</p>${['Tools & PPE: A1, 15 minutes of vocabulary','Technical processes: B1 and B2, 25 minutes','Automotive: A2 and engine description, 30 minutes','Electric vehicles: reading passage 2 and A3, 30 minutes','Energy: heat pump and B3, 30 minutes','Materials: B4, B5 and vocabulary review, 25 minutes','Practice exam 1: 90 minutes + review','Practice exam 2: 90 minutes + targeted revision'].map((t,i)=>`<label class="check"><input type="checkbox" ${state.plan[i]?'checked':''} onchange="state.plan[${i}]=this.checked;save();render()"><span>${i+1}. ${t}</span></label>`).join('')}</section><section class="card sectionhead"><h2>Exam progress</h2>${DATA.exams.map((_,n)=>`<p>Practice exam ${n+1}: ${state.exam[n]?.finished?scoreText(n):state.exam[n]?.started?'in progress':'not started'}</p>`).join('')}</section><div class="toolbar"><button onclick="download('Study-progress.json',JSON.stringify(state,null,2),'application/json')">Export backup</button></div><p class="muted">The backup contains your answers and writing. Clearing browser data or using another browser may make your local progress unavailable.</p>`}
function daysUntil(){const now=new Date(),d=new Date(state.testdate+'T12:00:00'),today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12);const days=Math.round((d-today)/86400000);return days>=0?`${days} days left. Spread the eight sessions across your available time and review mistakes between sessions.`:'Your selected date is in the past. You can set a new date.'}
function source(){return heading('Transparency','Built from your source file.','Exercises and answer keys from your Technical English practice file, dated 21 November 2026.')+`<div class="card"><h2>Content and sources</h2><ul><li>All 46 worksheet A/B exercises, both reading passages and both exams come from your file.</li><li>English grammar explanations, the study plan, module pages and missing term definitions are added study material.</li><li>The file does not provide a complete module structure. This website adds a topic-based organisation.</li><li>Exam 2, grammar question 6 is labelled Type 3 in the source. “If engineers had not discovered …, EVs would not exist today” is actually a mixed conditional: a past condition with a present consequence. The answer “had not discovered” remains valid.</li><li>Technical statements in the reading passages are practice material, not currently verified product or market advice.</li><li>40/60 is the practice target in the file; an official pass mark has not been confirmed.</li><li>Automatic checks compare answers with stored variants. Free writing requires self-assessment; no AI marking is provided.</li></ul><button class="secondary" onclick="download('Quelle.txt',DATA.source)">Download original file</button><p class="muted">The original source is in German. German terms remain only in bilingual vocabulary exercises.</p></div>`}

// ===== bridge to the AUTO ANATOMY 3D app (active only when embedded) =====
const EMBED=window.parent!==window;
const PART3D={'crankshaft':'crankshaft','piston':'piston','spark plug':'spark-plug','exhaust valve':'exhaust-valve','cylinder head':'cylinder-head','windscreen':'windshield','windshield':'windshield','boot':'trunk','trunk':'trunk','gearbox':'transmission','transmission':'transmission','cylinder':'cylinder','spanner':null};
function part3d(term){const t=String(term).toLowerCase().split(' / ');for(const x of t){const id=PART3D[x.trim()];if(id)return id}return null}
function m3d(term){const id=EMBED&&part3d(term);return id?`<button type="button" class="speak" onclick="parent.postMessage({type:'show3d',id:'${id}'},'*')" title="Show this part in the 3D car">🚗 3D</button>`:''}
function courseSummary(){const gs=groupStats();const best=Math.max(0,...DATA.exams.map((_,n)=>state.exam[n]?.finished?totalScore(n).auto+totalScore(n).manual:0));return {worksheetsCorrect:gs.reduce((a,g)=>a+g.c,0),attempted:gs.reduce((a,g)=>a+g.t,0),total:46,groups:gs,mistakes:mistakeIds().length,flashMastered:cards().filter(c=>(state.leitner[cardKey(c)]?.box||0)>=2).length,flashTotal:cards().length,flashDue:dueCards().length,readiness:readiness(),bestExam:best,examsDone:DATA.exams.filter((_,n)=>state.exam[n]?.finished).length,b1:(()=>{const b=levelStats('b1');return {c:b.c,t:b.t,n:b.n,groups:b.groups.map(g=>({id:g.id,title:g.title,c:g.c,t:g.t,n:g.n}))}})(),b2:(()=>{const b=levelStats('b2');return {c:b.c,t:b.t,n:b.n,groups:b.groups.map(g=>({id:g.id,title:g.title,c:g.c,t:g.t,n:g.n}))}})(),tests:Object.fromEntries(['b1','b2'].map(lv=>{const hst=(state.ltestHistory||{})[lv]||[];return [lv,{n:hst.length,best:hst.reduce((m,r)=>Math.max(m,Math.round(r.score/r.total*100)),0),last:hst.length?Math.round(hst[hst.length-1].score/hst[hst.length-1].total*100):null}]})),log:state.log,updated:Date.now()}}
function publish(){const sum=courseSummary();try{localStorage.setItem('werkstatt-summary',JSON.stringify(sum))}catch(e){}if(EMBED)parent.postMessage({type:'course-progress',summary:sum},'*')}
// In-page links: resolve '#route' against this page (inside an iframe srcdoc the base URL is the parent app)
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&!e.defaultPrevented&&!e.metaKey&&!e.ctrlKey){e.preventDefault();const r=a.getAttribute('href').slice(1);if(r==='main'){$('#main').focus();return}location.hash=r}});
window.addEventListener('message',e=>{const d=e.data||{};if(d.type==='theme'){state.theme=d.value;try{localStorage.setItem('werkstatt-v1',JSON.stringify(state))}catch(_){}applyTheme()}if(d.type==='go'&&d.route){location.hash=d.route}});
window.addEventListener('hashchange',render);if(EMBED)document.documentElement.classList.add('embedded');applyTheme();{const r=$('#rate');if(r)r.value=String(state.rate||0.9)}if(hasTTS)speechSynthesis.onvoiceschanged=()=>{};render();try{publish()}catch(e){}



